# Count shapes by T orientation and row/column arrangement. Encode output perhaps unique orientations and relative positions.
from collections import Counter
objs={
'd1':[(1,2),(2,2),(2,3),(2,4),(4,7),(4,8),(4,9),(5,8),(5,0),(5,1),(5,2),(6,1),(8,5),(8,6),(8,7),(9,6),(9,1),(10,1),(10,2),(10,3),(9,12),(10,12),(10,13),(10,14),(12,6),(12,7),(12,8),(13,7)],
'test':[(1,2),(2,1),(2,2),(2,3),(2,7),(2,8),(2,9),(3,8),(4,2),(4,3),(4,4),(5,3),(6,6),(6,7),(6,8),(7,2),(7,7),(8,1),(8,2),(8,3)]}
for k,pts in objs.items():
 S=set(pts); cs=[]
 while S:
  st=[S.pop()]; c=set(st)
  while st:
   r,x=st.pop()
   for q in ((r+1,x),(r-1,x),(r,x+1),(r,x-1)):
    if q in S:S.remove(q);c.add(q);st.append(q)
  cs.append(c)
 for c in sorted(cs,key=lambda c:min(c)):
  r0=min(r for r,x in c);c0=min(x for r,x in c)
  norm=sorted((r-r0,x-c0) for r,x in c)
  orient={((0,1),(1,0),(1,1),(1,2)):'down',((0,0),(0,1),(0,2),(1,1)):'up',((0,1),(1,1),(2,0),(2,1)):'left?',((0,0),(0,1),(1,1),(2,1)):'right?'}
  print(k,(r0,c0),norm, 'orient', next((v for pat,v in orient.items() if tuple(norm)==pat), '?'))

